1	/**
2	 * 赛狐 Temu 在售集合 diff → 下架 / 上架
3	 * 在售定义：selectStatus === "12"（已加入站点）
4	 *
5	 * 2026-07-31 防误报（服务器实锤）：
6	 * 某轮 getParentPageList 漏拉（unique 954→918），HomeCove 在售被算成 10，
7	 * 飞书误报「下架 5」；下一轮拉全又「上架 5」。半降护栏(50%)挡不住 15→10。
8	 *
9	 * 规则：
10	 *  1) 本店 allMap 相对上轮 allCount 掉太多 → 整轮 skip（接口不全）
11	 *  2) 「下架」必须：上轮在售，且本轮仍出现在 allMap 里、selectStatus ≠ 12
12	 *     （常见变 13）。完全从本轮结果消失的 SKC = 漏数，不告警、不从基准剔除
13	 *  3) 上架：本轮 12 且上轮不在 onSaleMap（首轮只建基准）
14	 */
15	import { SELECT_STATUS } from './products.js';
16	
17	/**
18	 * @param {object|null} prevSnap { onSaleMap, allCount, statusCounts, ts }
19	 * @param {{ onSaleMap: object, allMap?: object, statusCounts?: object, pullUnique?: number, prevPullUnique?: number }} curr
20	 */
21	export function diffOnSale(prevSnap, curr) {
22	  const prevMap = (prevSnap && prevSnap.onSaleMap) || null;
23	  const currMap = curr.onSaleMap || {};
24	  const allMap = curr.allMap || {};
25	  const currIds = Object.keys(currMap);
26	  const events = [];
27	  let skipUpdate = false;
28	
29	  const prevAllCount =
30	    typeof prevSnap?.allCount === 'number'
31	      ? prevSnap.allCount
32	      : null;
33	  const currAllCount = Object.keys(allMap).length;
34	
35	  // —— 全店商品数骤降：赛狐分页/限流漏数（实锤 954→918 级）——
36	  if (prevAllCount != null && prevAllCount >= 30 && currAllCount > 0) {
37	    if (currAllCount < Math.floor(prevAllCount * 0.92)) {
38	      skipUpdate = true;
39	      events.push({
40	        type: 'scan_incomplete',
41	        severity: 'warn',
42	        message: `本店商品列表疑似不全：上轮 all=${prevAllCount} → 本轮 ${currAllCount}，跳过上下架`,
43	      });
44	    }
45	  }
46	
47	  // —— 全局 unique 骤降（monitor 传入）——
48	  if (
49	    !skipUpdate &&
50	    typeof curr.prevPullUnique === 'number' &&
51	    typeof curr.pullUnique === 'number' &&
52	    curr.prevPullUnique >= 100 &&
53	    curr.pullUnique < Math.floor(curr.prevPullUnique * 0.95)
54	  ) {
55	    skipUpdate = true;
56	    events.push({
57	      type: 'scan_incomplete',
58	      severity: 'warn',
59	      message: `全量 unique 疑似不全：${curr.prevPullUnique} → ${curr.pullUnique}，跳过上下架`,
60	    });
61	  }
62	
63	  // —— 在售腰斩（旧护栏，保留）——
64	  if (!skipUpdate && prevMap) {
65	    const prevN = Object.keys(prevMap).length;
66	    const currN = currIds.length;
67	    if (prevN >= 5 && currN < Math.floor(prevN * 0.5)) {
68	      skipUpdate = true;
69	      events.push({
70	        type: 'scan_incomplete',
71	        severity: 'warn',
72	        message: `在售疑似不全：基准 ${prevN} → 本轮 ${currN}，跳过上下架判定`,
73	      });
74	    }
75	  }
76	
77	  let delisted = [];
78	  let listed = [];
79	  let ghosts = []; // 上轮在售、本轮 allMap 都没有 → 漏数，不当下架
80	
81	  if (prevMap && !skipUpdate) {
82	    const prevIds = Object.keys(prevMap);
83	
84	    for (const id of prevIds) {
85	      if (id in currMap) continue; // 仍在售
86	      const row = allMap[id];
87	      if (row && String(row.selectStatus) !== SELECT_STATUS.ON_SALE) {
88	        // 仍在本轮结果里，但已不是 12 → 真下架/离在售
89	        delisted.push(id);
90	      } else if (!row) {
91	        ghosts.push(id);
92	      } else {
93	        // row 存在且 status 仍是 12 但不在 currMap——不应发生；当 ghost 处理
94	        ghosts.push(id);
95	      }
96	    }
97	
98	    // 大量 ghost = 本轮漏拉，整轮作废（比误报下架安全）
99	    if (ghosts.length >= 3 || (prevIds.length >= 5 && ghosts.length >= 2 && ghosts.length >= Math.ceil(prevIds.length * 0.15))) {
100	      skipUpdate = true;
101	      delisted = [];
102	      events.push({
103	        type: 'scan_incomplete',
104	        severity: 'warn',
105	        message: `在售商品本轮失踪 ${ghosts.length} 个（未在结果中出现，疑似接口漏数），跳过上下架；样例 SKC ${ghosts.slice(0, 5).join(',')}`,
106	      });
107	    } else if (ghosts.length) {
108	      // 少数失踪：不告警，基准里先保留（nextSnap 合并 carry）
109	      events.push({
110	        type: 'scan_ghost',
111	        severity: 'warn',
112	        message: `在售商品本轮未出现 ${ghosts.length} 个（保留基准、不报下架）：${ghosts.slice(0, 8).join(',')}`,
113	        items: ghosts.map((id) => ({
114	          skcId: id,
115	          parentId: prevMap[id]?.parentId || '',
116	          name: prevMap[id]?.name || '',
117	        })),
118	      });
119	    }
120	
121	    listed = currIds.filter((id) => !(id in prevMap));
122	
123	    if (!skipUpdate && delisted.length) {
124	      events.push({
125	        type: 'delist',
126	        severity: 'alert',
127	        items: delisted.map((id) => ({
128	          skcId: id,
129	          parentId: (allMap[id] || prevMap[id])?.parentId || '',
130	          name: (allMap[id] || prevMap[id])?.name || '',
131	          selectStatus: allMap[id]?.selectStatus || prevMap[id]?.selectStatus || '',
132	        })),
133	        from: prevIds.length,
134	        to: currIds.length,
135	      });
136	    }
137	    if (!skipUpdate && listed.length) {
138	      events.push({
139	        type: 'onshelf',
140	        severity: 'alert',
141	        items: listed.map((id) => ({
142	          skcId: id,
143	          parentId: currMap[id]?.parentId || '',
144	          name: currMap[id]?.name || '',
145	          selectStatus: currMap[id]?.selectStatus || SELECT_STATUS.ON_SALE,
146	        })),
147	        from: prevIds.length,
148	        to: currIds.length,
149	      });
150	    }
151	  }
152	
153	  const isFirst = !prevMap;
154	
155	  // next onSaleMap：
156	  //  - skip → 整表沿用 prev
157	  //  - 否则用 curr，并把 ghost（漏数未证实下架）从 prev 带回来，避免下一轮假上架
158	  let nextOnSaleMap;
159	  if (skipUpdate && prevMap) {
160	    nextOnSaleMap = prevMap;
161	  } else if (prevMap && ghosts.length && !skipUpdate) {
162	    nextOnSaleMap = { ...currMap };
163	    for (const id of ghosts) {
164	      if (prevMap[id]) nextOnSaleMap[id] = prevMap[id];
165	    }
166	  } else {
167	    nextOnSaleMap = currMap;
168	  }
169	
170	  const nextSnap = {
171	    onSaleMap: nextOnSaleMap,
172	    statusCounts: skipUpdate && prevSnap?.statusCounts ? prevSnap.statusCounts : (curr.statusCounts || {}),
173	    onSaleCount: Object.keys(nextOnSaleMap).length,
174	    // 不全时 allCount 也不抬/砸，避免护栏失准
175	    allCount:
176	      skipUpdate && prevAllCount != null
177	        ? prevAllCount
178	        : currAllCount || prevAllCount || 0,
179	    ts: Date.now(),
180	  };
181	
182	  return {
183	    events,
184	    nextSnap,
185	    isFirst,
186	    skipUpdate,
187	    delistedCount: delisted.length,
188	    listedCount: skipUpdate ? 0 : listed.length,
189	    ghostCount: ghosts.length,
190	  };
191	}
192	
193	export function editLink(editBaseUrl, parentIdOrProductId) {
194	  const base = String(editBaseUrl || 'https://agentseller.temu.com').replace(/\/$/, '');
195	  // 后台编辑页参数多为 productId；赛狐 parentId 实测常等于商品父 ID，可点
196	  return `${base}/goods/edit?from=productList&productId=${parentIdOrProductId}`;
197	}
198	
199	function itemBullet(it, editBaseUrl) {
200	  const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 36);
201	  const pid = it.parentId || it.skcId;
202	  const st = it.selectStatus ? ` status=${it.selectStatus}` : '';
203	  return `• [${nm}](${editLink(editBaseUrl, pid)})  SKC ${it.skcId || '-'}${st}`;
204	}
205	
206	/**
207	 * 把 delist / onshelf 告警拼成飞书 lark_md 行
208	 * @param {string} storeName
209	 * @param {Array} events
210	 * @param {{ editBaseUrl?: string }} [opts]
211	 */
212	export function formatChangeLines(storeName, events, { editBaseUrl } = {}) {
213	  const lines = [`**🏬 ${storeName}**（赛狐 OpenAPI）`];
214	  let any = false;
215	  for (const ev of events) {
216	    if (ev.severity !== 'alert') continue;
217	    if (ev.type === 'delist' && ev.items?.length) {
218	      any = true;
219	      lines.push(
220	        `📉 在售商品**下架** ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}，离开 selectStatus=12）：`,
221	      );
222	      for (const it of ev.items.slice(0, 40)) lines.push(itemBullet(it, editBaseUrl));
223	      if (ev.items.length > 40) lines.push(`_…另有 ${ev.items.length - 40} 个未列出_`);
224	    }
225	    if (ev.type === 'onshelf' && ev.items?.length) {
226	      any = true;
227	      lines.push(
228	        `📈 在售商品**上架** ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}，进入 selectStatus=12）：`,
229	      );
230	      for (const it of ev.items.slice(0, 40)) lines.push(itemBullet(it, editBaseUrl));
231	      if (ev.items.length > 40) lines.push(`_…另有 ${ev.items.length - 40} 个未列出_`);
232	    }
233	  }
234	  if (!any) lines.push('_本轮无上下架_');
235	  lines.push('', `_检查时间：${new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })}_`);
236	  return lines;
237	}
238	
239	/** @deprecated 用 formatChangeLines；保留别名避免外部引用断裂 */
240	export function formatDelistLines(storeName, events, opts) {
241	  return formatChangeLines(storeName, events, opts);
242	}
243	
244	/**
245	 * 飞书卡片颜色：仅下架 red；仅上架 green；混合 orange
246	 * @param {Array} events
247	 */
248	export function alertTemplate(events) {
249	  const types = new Set(
250	    (events || []).filter((e) => e.severity === 'alert').map((e) => e.type),
251	  );
252	  const hasD = types.has('delist');
253	  const hasO = types.has('onshelf');
254	  if (hasD && hasO) return 'orange';
255	  if (hasO) return 'green';
256	  return 'red';
257	}
258	
259	export function alertTitle(events) {
260	  const types = new Set(
261	    (events || []).filter((e) => e.severity === 'alert').map((e) => e.type),
262	  );
263	  const hasD = types.has('delist');
264	  const hasO = types.has('onshelf');
265	  if (hasD && hasO) return '🔔 Temu 在售变动（赛狐）';
266	  if (hasO) return '🔔 Temu 上架监测（赛狐）';
267	  return '🔔 Temu 下架监测（赛狐）';
268	}
