27	/**
28	 * @param {object} cfg loadSellfoxConfig()
29	 * @param {{ dryRun?: boolean }} [opts]
30	 */
31	export async function runSellfoxOnce(cfg, opts = {}) {
32	  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
33	  if (!cfg.clientId || !cfg.clientSecret) throw new Error('缺少 clientId/clientSecret');
34	  if (!shops.length) throw new Error('没有店铺');
35	
36	  const client = createSellfoxClient({
37	    baseUrl: cfg.baseUrl,
38	    clientId: cfg.clientId,
39	    clientSecret: cfg.clientSecret,
40	    debug: cfg.debug,
41	  });
42	
43	  const shopIds = shops.map((s) => s.shopId);
44	  const names = shopNameMap(cfg);
45	
46	  log.info(`Sellfox 拉取 Temu 跨境父体：shops=${shopIds.join(',')} dateType=${cfg.dateType} lookback=${cfg.lookbackDays}d`);
47	  const { items, meta } = await fetchAllCrossParents(client, {
48	    shopIds,
49	    pageSize: cfg.pageSize,
50	    maxPagesPerWindow: cfg.maxPagesPerWindow,
51	    dateType: cfg.dateType,
52	    lookbackDays: cfg.lookbackDays,
53	  });
54	  log.info(`拉取完成 unique=${meta.unique} windows=${meta.windows}`);
55	
56	  const grouped = groupByShop(items, names);
57	  const state = loadState(cfg.stateFile);
58	  if (!state.stores) state.stores = {};
59	  const prevPullUnique =
60	    typeof state.meta?.pullUnique === 'number' ? state.meta.pullUnique : null;
61	
62	  const summary = [];
63	  let anySkip = false;
64	
65	  for (const shop of shops) {
66	    const sid = shop.shopId;
67	    const name = names[sid] || shop.name || sid;
68	    const g = grouped[sid] || {
69	      shopId: sid,
70	      shopName: name,
71	      onSaleMap: {},
72	      allMap: {},
73	      statusCounts: {},
74	    };
75	    const onSaleN = Object.keys(g.onSaleMap).length;
76	    const allN = Object.keys(g.allMap || {}).length;
77	    log.info(
78	      `${name}(${sid}) 在售(12)=${onSaleN} 全量=${allN} 状态分布=${JSON.stringify(g.statusCounts || {})}`,
79	    );
80	
81	    const prev = state.stores[sid]?.snapshot || null;
82	    const { events, nextSnap, isFirst, skipUpdate, ghostCount } = diffOnSale(prev, {
83	      onSaleMap: g.onSaleMap,
84	      allMap: g.allMap || {},
85	      statusCounts: g.statusCounts,
86	      pullUnique: meta.unique,
87	      prevPullUnique,
88	    });
89	
90	    for (const ev of events) {
91	      if (ev.severity === 'warn') log.warn(`${name} ${ev.message || ev.type}`);
92	    }
93	
94	    if (isFirst) {
95	      log.info(`${name} 首轮：建立在售基准 ${onSaleN}（全量 ${allN}），不告警`);
96	    } else if (skipUpdate) {
97	      anySkip = true;
98	      log.warn(`${name} 跳过上下架更新（扫描疑似不全${ghostCount ? ` ghost=${ghostCount}` : ''}）`);
99	    }
100	
101	    // 按配置过滤：delist / onshelf 可分别关闭（默认都开）
102	    const alertEvents = events.filter((e) => {
103	      if (e.severity !== 'alert') return false;
104	      if (e.type === 'delist') return cfg.alerts?.delist !== false;
105	      if (e.type === 'onshelf') return cfg.alerts?.onshelf !== false;
106	      return false;
107	    });
108	
109	    if (alertEvents.length && !opts.dryRun) {
110	      const lines = formatChangeLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl });
111	      await sendFeishu(
112	        { feishuWebhooks: cfg.feishuWebhooks, feishuSecret: cfg.feishuSecret },
113	        {
114	          title: alertTitle(alertEvents),
115	          template: alertTemplate(alertEvents),
116	          lines,
117	        },
118	      );
119	      const nDelist = alertEvents
120	        .filter((e) => e.type === 'delist')
121	        .reduce((n, e) => n + (e.items?.length || 0), 0);
122	      const nShelf = alertEvents
123	        .filter((e) => e.type === 'onshelf')
124	        .reduce((n, e) => n + (e.items?.length || 0), 0);
125	      const parts = [];
126	      if (nDelist) parts.push(`下架 ${nDelist}`);
127	      if (nShelf) parts.push(`上架 ${nShelf}`);
128	      log.info(`${name} 已告警${parts.join('、')} 个`);
129	    } else if (alertEvents.length && opts.dryRun) {
130	      log.info(
131	        `${name} dryRun:`,
132	        formatChangeLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl }),
133	      );
134	    } else if (!isFirst && !skipUpdate) {
135	      log.info(`${name} 本轮无上下架`);
136	    }
137	
138	    state.stores[sid] = {
139	      name,
140	      latest: {
141	        onSaleCount: nextSnap.onSaleCount,
142	        allCount: nextSnap.allCount,
143	        statusCounts: g.statusCounts,
144	        ts: Date.now(),
145	      },
146	      snapshot: nextSnap,
147	    };
148	    summary.push({
149	      shopId: sid,
150	      store: name,
151	      onSale: nextSnap.onSaleCount,
152	      allCount: nextSnap.allCount,
153	      statusCounts: g.statusCounts,
154	      events: events.map((e) => e.type),
155	      isFirst,
156	      skipUpdate,
157	      ghostCount,
158	    });
159	  }
160	
161	  // 配置了但本轮 API 完全没返回的店也建空基准提示
162	  for (const shop of shops) {
163	    if (!summary.find((s) => s.shopId === shop.shopId)) {
164	      summary.push({ shopId: shop.shopId, store: shop.name, onSale: 0, note: '无数据' });
165	    }
166	  }
167	
168	  // 只有本轮看起来完整时才刷新全局 unique，避免用残缺值当下一轮护栏基准
169	  if (!opts.dryRun) {
170	    if (!anySkip) {
171	      state.meta = {
172	        ...(state.meta || {}),
173	        pullUnique: meta.unique,
174	        pullTs: Date.now(),
175	        range: meta.range,
176	      };
177	    } else {
178	      log.warn(
179	        `本轮存在 skipUpdate，保留上轮 pullUnique=${prevPullUnique ?? '无'}（本轮 unique=${meta.unique} 不写入）`,
180	      );
181	    }
182	    saveState(cfg.stateFile, state);
183	  }
184	  return { meta, summary, onSaleStatus: SELECT_STATUS.ON_SALE };
185	}
186	
187	/** 只读探测：拉一窗并打印分布 */
188	export async function probeSellfox(cfg) {
189	  const client = createSellfoxClient({
190	    baseUrl: cfg.baseUrl,
191	    clientId: cfg.clientId,
192	    clientSecret: cfg.clientSecret,
193	    debug: cfg.debug,
194	  });
195	  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
196	  const shopIds = shops.map((s) => s.shopId);
197	  const { items, meta } = await fetchAllCrossParents(client, {
198	    shopIds,
199	    pageSize: cfg.pageSize,
200	    maxPagesPerWindow: cfg.maxPagesPerWindow,
201	    dateType: cfg.dateType,
202	    lookbackDays: Math.min(cfg.lookbackDays || 30, 30),
203	  });
204	  const grouped = groupByShop(items, shopNameMap(cfg));
205	  const byStatus = {};
206	  for (const it of items) {
207	    const st = it.selectStatus || '<empty>';
208	    byStatus[st] = (byStatus[st] || 0) + 1;
209	  }
210	  return {
211	    meta,
212	    byStatus,
213	    byShop: Object.fromEntries(
214	      Object.entries(grouped).map(([id, g]) => [
215	        id,
216	        {
217	          name: g.shopName,
218	          onSale12: Object.keys(g.onSaleMap).length,
219	          statusCounts: g.statusCounts,
220	        },
221	      ]),
222	    ),
223	    sampleOnSale: items
224	      .filter((i) => i.selectStatus === SELECT_STATUS.ON_SALE)
225	      .slice(0, 5)
226	      .map((i) => ({
227	        shop: i.shopName,
228	        skcId: i.skcId,
229	        parentId: i.parentId,
230	        name: i.productName.slice(0, 40),
231	        selectStatus: i.selectStatus,
232	      })),
233	  };
234	}
