        from: fromN,
        to: toN,
      });
    }
    if (!skipUpdate && listed.length) {
      events.push({
        type: 'onshelf',
        severity: 'alert',
        items: listed.map((id) => {
          const row = currMap[id] || prevPending[id] || {};
          return {
            skcId: id,
            parentId: row.parentId || '',
            name: row.name || '',
            selectStatus: row.selectStatus || SELECT_STATUS.ON_SALE,
          };
        }),
        from: fromN,
        to: toN,
      });
