  }

  const isFirst = !prevMap;

  // next onSaleMap：
  //  - skip → 整表沿用 prev，pending 也保留
  //  - 否则用 curr，并把 ghost（漏数未证实下架）从 prev 带回来，避免下一轮假上架
  let nextOnSaleMap;
  let nextPendingFinal = nextPending;
  if (skipUpdate && prevMap) {
    nextOnSaleMap = prevMap;
    nextPendingFinal = prevPending;
  } else if (prevMap && ghosts.length && !skipUpdate) {
    nextOnSaleMap = { ...currMap };
    for (const id of ghosts) {
      if (prevMap[id]) nextOnSaleMap[id] = prevMap[id];
